// ================================================================ extra recall item
QQ('fb_pb_issued', fb({
  t: 2, d: 2, c: 'recall',
  stem: 'Starting from the pass book balance, a cheque issued by the firm but not yet presented for payment is ___.',
  acc: [['deducted', 'subtracted', 'less']],
  sol: 'The pass book is higher than the cash book by the amount of the cheque, so it is deducted to reach the cash book balance.',
}));
